'use strict';

// MODULES //

var iterationOrder = require( '@stdlib/ndarray/base/iteration-order' );
var ndarray2object = require( '@stdlib/ndarray/base/ndarraylike2object' );
var numel = require( '@stdlib/ndarray/base/numel' );
var blockedaccessorUntilEach2d = require( './2d_blocked_accessors.js' );
var blockedaccessorUntilEach3d = require( './3d_blocked_accessors.js' );
var blockedaccessorUntilEach4d = require( './4d_blocked_accessors.js' );
var blockedaccessorUntilEach5d = require( './5d_blocked_accessors.js' );
var blockedaccessorUntilEach6d = require( './6d_blocked_accessors.js' );
var blockedaccessorUntilEach7d = require( './7d_blocked_accessors.js' );
var blockedaccessorUntilEach8d = require( './8d_blocked_accessors.js' );
var blockedaccessorUntilEach9d = require( './9d_blocked_accessors.js' );
var blockedaccessorUntilEach10d = require( './10d_blocked_accessors.js' );
var blockedUntilEach2d = require( './2d_blocked.js' );
var blockedUntilEach3d = require( './3d_blocked.js' );
var blockedUntilEach4d = require( './4d_blocked.js' );
var blockedUntilEach5d = require( './5d_blocked.js' );
var blockedUntilEach6d = require( './6d_blocked.js' );
var blockedUntilEach7d = require( './7d_blocked.js' );
var blockedUntilEach8d = require( './8d_blocked.js' );
var blockedUntilEach9d = require( './9d_blocked.js' );
var blockedUntilEach10d = require( './10d_blocked.js' );
var accessorUntilEach0d = require( './0d_accessors.js' );
var accessorUntilEach1d = require( './1d_accessors.js' );
var accessorUntilEach2d = require( './2d_accessors.js' );
var accessorUntilEach3d = require( './3d_accessors.js' );
var accessorUntilEach4d = require( './4d_accessors.js' );
var accessorUntilEach5d = require( './5d_accessors.js' );
var accessorUntilEach6d = require( './6d_accessors.js' );
var accessorUntilEach7d = require( './7d_accessors.js' );
var accessorUntilEach8d = require( './8d_accessors.js' );
var accessorUntilEach9d = require( './9d_accessors.js' );
var accessorUntilEach10d = require( './10d_accessors.js' );
var accessorUntilEachnd = require( './nd_accessors.js' );
var untilEach0d = require( './0d.js' );
var untilEach1d = require( './1d.js' );
var untilEach2d = require( './2d.js' );
var untilEach3d = require( './3d.js' );
var untilEach4d = require( './4d.js' );
var untilEach5d = require( './5d.js' );
var untilEach6d = require( './6d.js' );
var untilEach7d = require( './7d.js' );
var untilEach8d = require( './8d.js' );
var untilEach9d = require( './9d.js' );
var untilEach10d = require( './10d.js' );
var untilEachnd = require( './nd.js' );


// VARIABLES //

var UNTIL_EACH = [
	untilEach0d,
	untilEach1d,
	untilEach2d,
	untilEach3d,
	untilEach4d,
	untilEach5d,
	untilEach6d,
	untilEach7d,
	untilEach8d,
	untilEach9d,
	untilEach10d
];
var ACCESSOR_UNTIL_EACH = [
	accessorUntilEach0d,
	accessorUntilEach1d,
	accessorUntilEach2d,
	accessorUntilEach3d,
	accessorUntilEach4d,
	accessorUntilEach5d,
	accessorUntilEach6d,
	accessorUntilEach7d,
	accessorUntilEach8d,
	accessorUntilEach9d,
	accessorUntilEach10d
];
var BLOCKED_UNTIL_EACH = [
	blockedUntilEach2d, // 0
	blockedUntilEach3d,
	blockedUntilEach4d,
	blockedUntilEach5d,
	blockedUntilEach6d,
	blockedUntilEach7d,
	blockedUntilEach8d,
	blockedUntilEach9d,
	blockedUntilEach10d // 8
];
var BLOCKED_ACCESSOR_UNTIL_EACH = [
	blockedaccessorUntilEach2d, // 0
	blockedaccessorUntilEach3d,
	blockedaccessorUntilEach4d,
	blockedaccessorUntilEach5d,
	blockedaccessorUntilEach6d,
	blockedaccessorUntilEach7d,
	blockedaccessorUntilEach8d,
	blockedaccessorUntilEach9d,
	blockedaccessorUntilEach10d // 8
];
var MAX_DIMS = UNTIL_EACH.length - 1;


// MAIN //

/**
* Invokes a callback function for each element in an ndarray until a predicate function returns a truthy value.
*
* ## Notes
*
* -   A provided ndarray should be an object with the following properties:
*
*     -   **dtype**: data type.
*     -   **data**: data buffer.
*     -   **shape**: dimensions.
*     -   **strides**: stride lengths.
*     -   **offset**: index offset.
*     -   **order**: specifies whether an ndarray is row-major (C-style) or column major (Fortran-style).
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing one input array
* @param {Function} predicate - predicate function
* @param {Callback} fcn - callback function
* @param {*} [thisArg] - callback function execution context
* @returns {void}
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var naryFunction = require( '@stdlib/utils/nary-function' );
* var log = require( '@stdlib/console/log' );
*
* function predicate() {
*     return false;
* }
*
* // Create a data buffer:
* var xbuf = new Float64Array( 12 );
*
* // Define the shape of the array:
* var shape = [ 3, 1, 2 ];
*
* // Define the array strides:
* var sx = [ 4, 4, 1 ];
*
* // Define the index offset:
* var ox = 1;
*
* // Create an ndarray-like object:
* var x = {
*     'ref': null,
*     'dtype': 'float64',
*     'data': xbuf,
*     'shape': shape,
*     'strides': sx,
*     'offset': ox,
*     'order': 'row-major'
* };
*
* // Apply the callback function:
* untilEach( [ x ], predicate, naryFunction( log, 1 ) );
*/
function untilEach( arrays, predicate, fcn, thisArg ) {
	var ndims;
	var shx;
	var x;

	// Unpack the ndarray and standardize ndarray meta data:
	x = ndarray2object( arrays[ 0 ] );
	shx = x.shape;
	ndims = shx.length;

	// Determine whether we can avoid iteration altogether...
	if ( ndims === 0 ) {
		if ( x.accessorProtocol ) {
			return ACCESSOR_UNTIL_EACH[ ndims ]( x, predicate, fcn, thisArg );
		}
		return UNTIL_EACH[ ndims ]( x, predicate, fcn, thisArg );
	}
	// Check whether we were provided an empty ndarray...
	if ( numel( shx ) === 0 ) {
		return;
	}
	// Determine whether we can avoid blocked iteration...
	if ( ndims <= MAX_DIMS && iterationOrder( x.strides ) !== 0 ) {
		// So long as iteration always moves in the same direction (i.e., no mixed sign strides), we can leverage cache-optimal (i.e., normal) nested loops without resorting to blocked iteration...
		if ( x.accessorProtocol ) {
			return ACCESSOR_UNTIL_EACH[ ndims ]( x, predicate, fcn, thisArg );
		}
		return UNTIL_EACH[ ndims ]( x, predicate, fcn, thisArg );
	}
	// Determine whether we can perform blocked iteration...
	if ( ndims <= MAX_DIMS ) {
		if ( x.accessorProtocol ) {
			return BLOCKED_ACCESSOR_UNTIL_EACH[ ndims-2 ]( x, predicate, fcn, thisArg ); // eslint-disable-line max-len
		}
		return BLOCKED_UNTIL_EACH[ ndims-2 ]( x, predicate, fcn, thisArg );
	}
	// Fall-through to linear view iteration without regard for how data is stored in memory (i.e., take the slow path)...
	if ( x.accessorProtocol ) {
		return accessorUntilEachnd( x, predicate, fcn, thisArg );
	}
	untilEachnd( x, predicate, fcn, thisArg );
}


// EXPORTS //

module.exports = untilEach;
